window.APP_CONTENT = {
  en: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  hi: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  bn: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  mr: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  gu: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  pa: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  or: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  ta: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  te: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  kn: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  ml: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}},
  ur: {"ing":{"onion":"Onion|onions|red onion|shallots","tomato":"Tomato|tomatoes","potato":"Potato|potatoes|baby potatoes","green_chilli":"Green chilli|green chillies|green chili|chilli","ginger":"Ginger|fresh ginger","garlic":"Garlic|garlic cloves","coriander":"Coriander leaves|coriander|cilantro|fresh coriander","curry_leaves":"Curry leaves|curry leaf","mint":"Mint|mint leaves|pudina leaves","lemon":"Lemon|lemons|lime|lemon juice","carrot":"Carrot|carrots","peas":"Green peas|peas|frozen peas|matar peas","cauliflower":"Cauliflower|gobi","cabbage":"Cabbage","capsicum":"Capsicum|bell pepper|green capsicum","brinjal":"Brinjal|eggplant|aubergine|baingan","okra":"Okra|lady finger|ladies finger|bhindi","spinach":"Spinach|spinach leaves","methi":"Fenugreek leaves|fresh methi","lauki":"Bottle gourd|lauki|doodhi","karela":"Bitter gourd|karela","pumpkin":"Pumpkin|red pumpkin|yellow pumpkin","cucumber":"Cucumber|cucumbers","beans":"French beans|green beans|beans","beetroot":"Beetroot|beet","corn":"Sweet corn|corn|corn kernels","mushroom":"Mushroom|mushrooms|button mushroom","raw_mango":"Raw mango|green mango","coconut":"Coconut|grated coconut|fresh coconut|desiccated coconut","sarson":"Mustard greens|mustard leaves","drumstick":"Drumstick|drumsticks|moringa pods","milk":"Milk|full cream milk|cow milk","curd":"Curd|yogurt|yoghurt|dahi|plain yogurt","paneer":"Paneer|cottage cheese","cream":"Fresh cream|cream|malai","cheese":"Cheese|cheese slices|processed cheese","ghee":"Ghee|clarified butter","butter":"Butter","rice":"Rice|basmati rice|raw rice|cooked rice","atta":"Wheat flour|atta|whole wheat flour|chapati flour","maida":"Maida|all-purpose flour|refined flour","besan":"Besan|gram flour|chickpea flour","suji":"Suji|semolina|rava","rice_flour":"Rice flour","ragi":"Ragi flour|finger millet flour","jowar":"Jowar flour|sorghum flour","makki_atta":"Maize flour|makki atta|yellow corn flour","oats":"Oats|rolled oats|instant oats","sattu":"Sattu|roasted gram flour","poha":"Poha|flattened rice|beaten rice","sabudana":"Sabudana|sago|tapioca pearls","murmura":"Puffed rice|murmura","vermicelli":"Vermicelli|seviyan","toor":"Toor dal|arhar dal|pigeon pea|split pigeon peas","moong_dal":"Moong dal|yellow moong dal|split moong","moong_whole":"Whole green moong","masoor":"Masoor dal|red lentils","chana_dal":"Chana dal|split Bengal gram","urad":"Urad dal|split white urad|black gram dal","urad_whole":"Whole black urad","rajma":"Rajma|red kidney beans","kabuli":"Chickpeas|kabuli chana|chole","kala_chana":"Black chana|kala chana|brown chickpeas","sprouts":"Moong sprouts|sprouted moong","dried_peas":"Dried white peas|dried yellow peas","peanuts":"Peanuts|groundnuts","roasted_gram":"Roasted gram|roasted chana dal","soya":"Soya chunks","turmeric":"Turmeric|turmeric powder|haldi","red_chilli":"Red chilli powder|chilli powder|Kashmiri chilli powder","cumin":"Cumin seeds|cumin|jeera|roasted cumin powder","mustard_seeds":"Mustard seeds","coriander_powder":"Coriander powder","garam_masala":"Garam masala","hing":"Asafoetida|hing","dry_red_chilli":"Dry red chillies|whole red chilli","methi_seeds":"Fenugreek seeds|methi seeds","fennel":"Fennel seeds|saunf","cardamom":"Cardamom|green cardamom|elaichi powder","cloves":"Cloves","cinnamon":"Cinnamon|cinnamon stick","bay_leaf":"Bay leaf|bay leaves","black_pepper":"Black pepper|pepper|pepper powder","kasuri_methi":"Kasuri methi|dried fenugreek leaves","amchur":"Dry mango powder|amchur","chaat_masala":"Chaat masala","ajwain":"Carom seeds|ajwain","sambar_powder":"Sambar powder","pav_bhaji_masala":"Pav bhaji masala","panch_phoron":"Panch phoron (five-seed mix)","kalonji":"Nigella seeds|kalonji","saffron":"Saffron|kesar","sesame":"Sesame seeds|til","poppy":"Poppy seeds|khus khus|posto","black_salt":"Black salt|kala namak","sonth":"Dry ginger powder|sonth","salt":"Salt","sugar":"Sugar","jaggery":"Jaggery|gur","oil":"Cooking oil|oil|vegetable oil|refined oil","mustard_oil":"Mustard oil","coconut_oil":"Coconut oil","water":"Water","tea":"Tea leaves|tea powder|chai patti","coffee":"Coffee powder","honey":"Honey","tamarind":"Tamarind","kokum":"Kokum","soda":"Baking soda","eno":"Fruit salt (Eno)","milk_powder":"Milk powder","banana":"Banana|bananas|ripe banana","cashew":"Cashews|cashew nuts|kaju","raisins":"Raisins|kishmish","almonds":"Almonds|badam","makhana":"Makhana|fox nuts|lotus seeds","egg":"Egg|eggs","chicken":"Chicken","fish":"Fish|fish pieces","mutton":"Mutton|goat meat","prawns":"Prawns|shrimp","bread":"Bread|bread slices","pav":"Pav|soft bread rolls","pasta":"Pasta|macaroni","sev":"Sev (thin namkeen)","batter":"Idli-dosa batter"},"rec":{"poha":["Kanda Poha","Rinse the poha in a sieve under running water for a few seconds, drain it and leave it for 5 minutes to soften.","Mix salt, turmeric and sugar into the soft poha. Chop the onion and green chillies; cut the potato into small cubes.","Heat oil in a kadhai. Fry the peanuts till crisp, take them out. Add mustard seeds and let them splutter, then curry leaves and green chillies.","Add the onion and potato. Cover and cook on low heat till the potato is soft.","Add the poha and peanuts, mix gently, cover and cook for 2 to 3 minutes on low heat.","Squeeze lemon, top with coriander and serve hot."],"upma":["Rava Upma","Dry roast the suji in a kadhai on low heat till it smells nice and looks light golden. Keep it aside.","Heat oil. Add mustard seeds, urad dal and chana dal; fry till golden. Add curry leaves, chopped green chillies and ginger.","Add the chopped onion and fry till soft.","Pour in the water with salt and bring it to a boil.","Lower the heat and add the suji slowly while stirring, so no lumps form. Cover and cook for 3 to 4 minutes.","Add ghee, mix, top with coriander and serve hot with chutney."],"aloo_paratha":["Aloo Paratha","Knead the atta with a pinch of salt and water into a soft dough. Cover and rest for 15 minutes.","Boil the potatoes till soft (about 3 whistles in a cooker), peel and mash them well.","Mix the mashed potato with chopped green chilli, ginger, coriander, red chilli, amchur, garam masala, ajwain and salt.","Roll a ball of dough into a small circle, put a big spoon of filling in the middle, close it from all sides and roll it out gently.","Cook on a hot tawa. Flip, apply ghee on both sides and cook till golden brown spots appear. Serve with curd or pickle."],"besan_chilla":["Besan Chilla","Finely chop the onion, tomato, green chilli and coriander.","Mix besan, turmeric, red chilli, ajwain and salt with water into a smooth, flowing batter. Rest it for 5 minutes, then add the chopped vegetables.","Heat a tawa and grease it with oil. Pour a ladle of batter and spread it into a thin round. Cook till the bottom turns golden.","Flip, add a few drops of oil around the edge and cook the other side. Serve hot with green chutney or ketchup."],"idli":["Idli","Wash and soak the rice in one bowl, and the urad dal with methi seeds in another, for 5 to 6 hours.","Grind the urad dal to a very smooth, fluffy batter with a little water. Grind the rice to a slightly coarse batter.","Mix both batters with salt in a big vessel. Cover and keep it in a warm place overnight (8 to 12 hours) till it rises.","Grease the idli plates, fill them three-fourths with batter and steam for 10 to 12 minutes.","Wait for 2 minutes, then take the idlis out with a wet spoon. Serve with sambar and coconut chutney."],"dosa":["Plain Dosa","Soak the rice, and the urad dal with methi seeds, separately for 5 to 6 hours.","Grind both to a smooth batter, mix with salt and leave it covered overnight to ferment.","Stir the batter. It should flow like thick buttermilk; add a little water if needed.","Heat a tawa well, sprinkle water and wipe it. Pour a ladle of batter in the centre and spread it in circles to make it thin.","Drizzle oil around the edges and cook till the bottom is golden and crisp. Fold and serve with chutney and sambar."],"masala_dosa":["Masala Dosa","Boil, peel and roughly mash the potatoes.","Heat 1 tablespoon oil. Add mustard seeds and urad dal, then curry leaves, green chillies, ginger and sliced onion. Fry till the onion is soft.","Add turmeric, salt and the potatoes with a splash of water. Mix well, cook for 2 minutes and add coriander. The masala is ready.","Spread a ladle of batter thin on a hot tawa, drizzle oil and cook till crisp and golden.","Put 2 spoons of potato masala in the middle, fold the dosa and serve hot with chutney and sambar."],"rava_dosa":["Rava Dosa","Mix suji, rice flour, maida, salt and water into a very thin, watery batter. Rest it for 20 minutes.","Add chopped onion, green chilli, ginger, curry leaves, cumin and crushed pepper. Stir well every time before pouring.","Heat a tawa till very hot. Pour the batter from a height all over the tawa, filling only the big gaps. Do not spread it.","Drizzle oil and cook on medium heat till the dosa turns crisp and golden. Fold and serve hot."],"sabudana_khichdi":["Sabudana Khichdi","Wash the sabudana 2 or 3 times, then soak it in just enough water to cover it for 5 to 6 hours or overnight. It should press easily between fingers.","Dry roast the peanuts, rub off the skins and crush them coarsely. Mix them with the sabudana, salt and sugar.","Heat ghee. Add cumin, curry leaves and green chillies, then the boiled or finely cut potato. Cook till the potato is soft.","Add the sabudana mix and stir gently on low heat till the pearls turn see-through, about 5 to 6 minutes.","Squeeze lemon, add coriander and serve hot. For fasting, use sendha namak."],"veg_sandwich":["Vegetable Sandwich","Slice the cucumber, tomato, onion and boiled potato into thin rounds.","Spread butter on one side of each bread slice.","Layer the vegetables on two slices, sprinkle chaat masala, salt and pepper, and cover with the other slices.","Eat it as it is, or toast it on a tawa or in a toaster till golden. Cut into triangles and serve with ketchup."],"bread_omelette":["Bread Omelette","Beat the eggs with chopped onion, green chilli, tomato, coriander, salt and pepper.","Melt butter on a tawa and pour half of the egg mix. Quickly dip two bread slices in it and place them on top.","When the egg sets, flip it all over. Fold the extra omelette edges over the bread.","Cook till both sides are golden. Make the second one the same way and serve with ketchup."],"masala_omelette":["Masala Omelette","Chop the onion, tomato, green chilli and coriander very fine.","Beat the eggs well with salt, turmeric, red chilli and the chopped vegetables.","Heat oil in a pan, pour the egg mix and spread it. Cook on medium heat till the bottom sets.","Flip carefully and cook the other side for a minute. Serve hot with bread or roti."],"egg_bhurji":["Egg Bhurji","Heat butter in a pan. Fry chopped onion and green chilli till soft.","Add chopped tomato, turmeric, red chilli and salt. Cook till the tomato is soft.","Break the eggs into the pan and keep stirring so they cook into soft, small pieces.","Add garam masala and coriander. Serve hot with pav, bread or roti."],"methi_thepla":["Methi Thepla","Wash and finely chop the methi leaves.","Mix atta, besan, methi, all spices, salt, crushed ginger and chilli, 1 tablespoon oil and curd. Knead a soft dough with a little water and rest it for 10 minutes.","Make small balls and roll each one into a thin circle, using a little dry flour.","Cook on a hot tawa with a little oil on both sides till light brown spots appear. Theplas stay good for 2 days, great for travel."],"ven_pongal":["Ven Pongal","Dry roast the moong dal for 2 to 3 minutes till it smells nice. Wash it with the rice.","Pressure cook the rice and dal with water and salt for 4 to 5 whistles, till very soft. Mash lightly.","Heat ghee. Fry cashews till golden, then add pepper, cumin, grated ginger, curry leaves and hing.","Pour this tadka over the pongal, mix well, add a little hot water if it is too thick. Serve with coconut chutney and sambar."],"uttapam":["Onion Tomato Uttapam","Finely chop the onion, tomato, green chilli, capsicum, carrot and coriander. Mix with a pinch of salt.","Heat and grease a tawa. Pour a ladle of thick batter and spread it into a thick, small round.","Sprinkle the vegetables on top and press them lightly. Drizzle oil around and cook on medium heat till the bottom is golden.","Flip and cook for 2 minutes more. Serve hot with chutney."],"masala_oats":["Masala Oats","Heat oil. Add cumin, then chopped onion and green chilli. Fry for 2 minutes.","Add chopped tomato, carrot, peas, turmeric and salt. Cook till soft.","Add oats and water. Stir and cook for 3 to 4 minutes till it becomes thick like porridge.","Top with coriander and serve hot."],"ragi_porridge":["Ragi Porridge (Ragi Malt)","Mix the ragi flour in 1 cup of cold water till there are no lumps.","Cook it on low heat, stirring all the time, till it turns thick and glossy, about 5 to 6 minutes.","Add milk, grated jaggery and crushed cardamom. Boil for 2 to 3 minutes more, stirring.","Serve warm. For a salty version, skip jaggery and mix in buttermilk and salt when cool."],"puri":["Puri","Mix atta, salt, ajwain and 1 tablespoon oil. Knead a stiff, smooth dough with a little water and rest it for 10 minutes.","Make small balls and roll them into small circles, not too thin. Use a drop of oil instead of dry flour.","Heat oil in a kadhai. It is ready when a small piece of dough rises at once.","Slide in one puri, press gently with the ladle so it puffs up, flip and fry till light golden. Drain on paper and serve with aloo sabzi or halwa."],"akki_roti":["Akki Roti","Mix rice flour, finely chopped onion, grated carrot, green chilli, coriander, coconut, cumin, curry leaves and salt.","Add warm water little by little and knead a soft dough.","Grease a cold tawa or a banana leaf, put a ball of dough and pat it thin with wet fingers.","Make a few holes, add oil, and cook covered on medium heat. Flip and cook till both sides have brown spots. Serve with chutney."],"moong_chilla":["Moong Dal Chilla","Wash and soak the moong dal for 3 to 4 hours.","Drain and grind it with ginger, green chilli and a little water into a smooth, thick batter. Add cumin, hing, salt and coriander.","Spread a ladle of batter thin on a hot greased tawa. Add grated paneer on top if you like. Drizzle oil.","Flip once the bottom is golden and cook the other side. Serve with green chutney."],"misal_pav":["Misal Pav","Pressure cook the sprouts with salt, turmeric and 1 cup water for 1 to 2 whistles. They should stay whole.","Fry 1 onion, ginger, garlic and coconut in a little oil till brown. Cool and grind to a paste with the tomato.","Heat the rest of the oil, add mustard seeds, then the paste, red chilli and garam masala. Fry till oil separates.","Add the sprouts and 2 cups water. Boil for 8 to 10 minutes to make a spicy thin gravy (rassa).","Serve the misal in a bowl topped with chopped onion, sev, coriander and lemon, with soft pav."],"chuda_dahi":["Chuda Dahi","Wash the poha once and leave it in a sieve for 2 to 3 minutes to soften a little.","Put it in a bowl and add thick curd.","Add crushed jaggery or sugar and banana slices. Mix and eat at once. A cool Bihar breakfast, popular on Makar Sankranti."],"pesarattu":["Pesarattu","Wash and soak the whole moong (and rice) for 6 hours or overnight.","Grind with ginger, green chillies, cumin, salt and a little water into a smooth batter.","Spread a ladle of batter thin on a hot tawa, sprinkle chopped onion and drizzle oil. Cook till crisp.","Fold and serve hot with ginger chutney or upma, the Andhra way."],"thalipeeth":["Thalipeeth","Mix all the flours with chopped onion, chilli, coriander, spices, sesame and salt.","Add water little by little and knead a soft dough.","Put a ball of dough on a greased plastic sheet or a cold tawa and pat it thin with wet fingers. Make 4 to 5 holes in it.","Put oil in the holes and cook covered on medium heat. Flip and cook till crisp. Serve with curd or white butter."],"dhokla":["Khaman Dhokla","Mix besan, suji, turmeric, salt, 1 tablespoon sugar, half the lemon juice, crushed ginger-chilli, 1 tablespoon oil and about 3/4 cup water into a smooth batter.","Heat water in a steamer and grease a plate. Just before steaming, add eno and stir gently till the batter turns frothy.","Pour into the plate at once and steam for 12 to 15 minutes, till a knife comes out clean. Cool a little and cut into pieces.","For the tadka, heat oil, add mustard seeds, hing, curry leaves and slit chillies. Add 1/4 cup water, the rest of the sugar and lemon juice, and boil once.","Pour the tadka over the dhokla, top with coriander and serve."],"luchi":["Luchi","Rub ghee and salt into the maida. Knead a soft, smooth dough with water. Cover and rest for 15 minutes.","Make small balls and roll them into thin circles with a drop of oil.","Fry one at a time in hot oil, pressing lightly so it puffs up. Take it out while it is still white, not brown.","Serve hot with cholar dal, aloo dum or begun bhaja."],"dal_tadka":["Dal Tadka","Wash the toor dal and pressure cook it with turmeric, salt and water for 3 to 4 whistles, till soft. Whisk it smooth.","Heat 1 tablespoon ghee. Fry chopped onion, ginger, garlic and green chilli till golden, then add tomato and cook till soft.","Add the cooked dal and a little water if it is thick. Boil for 5 minutes.","For the tadka, heat the rest of the ghee, add cumin, dry red chillies, hing and red chilli powder, and pour it over the dal at once.","Top with coriander and serve with rice or roti."],"moong_dal":["Yellow Moong Dal","Wash the moong dal and pressure cook it with turmeric, salt and water for 2 whistles. It cooks fast.","Heat ghee. Add cumin and hing, then grated ginger and slit green chilli.","Add chopped tomato and cook till soft, then add the dal. Boil for 3 to 4 minutes.","Add lemon juice and coriander. A light dal, good for children and anyone who is unwell."],"masoor_dal":["Masoor Dal (Bengali style)","Wash the masoor dal and boil it with turmeric, salt and water till soft, about 12 minutes in a pot (or 2 whistles). Whisk it smooth.","Heat mustard oil till it smokes lightly. Add kalonji and slit green chillies, then sliced onion and garlic. Fry till golden.","Add chopped tomato, then the dal. Boil for 5 minutes. The dal should be thin and flowing.","Add coriander and serve with hot rice."],"sambar":["Sambar","Pressure cook the toor dal with turmeric and water for 3 to 4 whistles and mash it well. Soak the tamarind in 1 cup warm water and squeeze out the juice.","Boil the chopped vegetables (onion, drumstick, brinjal, pumpkin, tomato) with salt in a little water till just soft.","Add the tamarind water and sambar powder. Boil for 5 minutes till the raw smell goes.","Add the mashed dal and jaggery. Simmer for 5 minutes.","For the tadka, heat oil, add mustard seeds, dry red chillies, curry leaves and hing, and pour over the sambar. Add coriander and serve with rice, idli or dosa."],"rasam":["Tomato Rasam","Soak the tamarind in 1/2 cup warm water and squeeze out the juice. Crush the pepper, cumin and garlic coarsely.","Boil the chopped tomatoes with tamarind water, turmeric, salt and the crushed spices till the tomatoes are soft and mushy.","Add the cooked toor dal water (if using) and more water. Heat till it turns frothy on top. Do not boil hard.","Heat ghee, add mustard seeds, dry red chilli, curry leaves and hing, and pour over the rasam.","Add lots of coriander. Drink it hot, or have it with rice. Good for a cold."],"rajma":["Rajma Masala","Wash the rajma and soak it in plenty of water for 8 hours or overnight.","Pressure cook the soaked rajma with salt and fresh water for 6 to 8 whistles, till a bean mashes easily.","Heat oil. Add cumin and bay leaf, then finely chopped onion. Fry till golden brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices. Cook till the oil separates.","Add the rajma with its water. Mash a few beans to thicken the gravy and simmer for 15 minutes. Serve with rice."],"chole":["Chole Masala","Wash and soak the chickpeas overnight in plenty of water.","Tie the tea leaves in a small cloth (for a dark colour). Pressure cook the chickpeas with it, salt and water for 5 to 6 whistles till soft. Remove the tea bundle.","Heat oil. Add cumin and bay leaf, then chopped onion; fry till brown. Add ginger, garlic and green chilli.","Add tomato puree and all the powder spices except garam masala and amchur. Cook till the oil separates.","Add the chickpeas with their water, garam masala and amchur. Mash a few, simmer for 15 minutes. Serve with puri, bhature or rice."],"dal_makhani":["Dal Makhani","Wash and soak the whole urad and rajma overnight.","Pressure cook them with salt and water for 8 to 10 whistles, till very soft and creamy.","Heat butter. Add cumin, chopped onion, ginger and garlic. Fry, then add tomato puree and red chilli. Cook till thick.","Add the cooked dal and mash a little. Simmer on low heat for 30 minutes or more, stirring often. The longer, the creamier.","Add garam masala, crushed kasuri methi and cream. Serve with naan, roti or jeera rice."],"cholar_dal":["Cholar Dal","Wash and soak the chana dal for 1 hour.","Pressure cook with turmeric, salt and water for 3 whistles. The dal should be soft but not mushy.","Heat ghee. Fry small coconut pieces till golden. Add cumin, bay leaf, dry red chillies and the whole spices, then grated ginger.","Add the dal, sugar and raisins. Boil for 5 minutes. Serve with luchi, a Bengali festival favourite with no onion or garlic."],"gujarati_dal":["Gujarati Dal","Pressure cook the toor dal with peanuts, turmeric and water for 3 to 4 whistles. Whisk it very smooth.","Add more water to make it thin, then tomato, crushed ginger-chilli, jaggery, kokum, red chilli and salt. Boil.","Heat ghee. Add mustard seeds, cumin, methi seeds, cloves, curry leaves and hing. Pour into the dal.","Simmer for 10 minutes. Add lemon juice. The dal should taste sweet, sour and a little spicy. Serve with rice."],"dal_palak":["Dal Palak","Pressure cook the toor dal with turmeric, salt and water for 3 whistles.","Wash the spinach well in plenty of water and chop it.","Heat ghee. Add cumin, garlic, green chilli and onion; fry till golden. Add tomato and red chilli and cook till soft.","Add the spinach and cook for 2 minutes, then add the dal. Boil for 5 minutes. Serve with rice or roti."],"varan":["Varan","Wash the toor dal and pressure cook it with turmeric, hing and water for 4 whistles, till very soft.","Whisk it smooth, add salt, jaggery and a little water. Boil for 2 to 3 minutes.","Serve over hot rice with a spoon of ghee and a squeeze of lemon: Maharashtrian varan bhaat. Simple, with no onion or garlic."],"kadhi_pakora":["Kadhi Pakora","For pakoras, mix 1/3 cup besan with sliced onion, ajwain, salt and a little water into a thick batter.","Drop small spoons of batter into hot oil and fry till golden. Keep aside.","Whisk the curd with the remaining besan, turmeric, red chilli and 3 cups water till smooth.","Heat ghee. Add methi seeds, cumin, dry red chillies, hing and ginger. Pour in the curd mix and keep stirring till it boils. Simmer on low heat for 20 minutes.","Add salt and the pakoras and cook for 5 minutes. Serve with rice."],"gujarati_kadhi":["Gujarati Kadhi","Whisk the curd, besan and water till very smooth. Add sugar, salt, crushed ginger and green chilli.","Bring it to a boil on medium heat, stirring all the time so it does not split. Simmer for 8 to 10 minutes.","Heat ghee, add mustard seeds, cumin, cloves, cinnamon, curry leaves and hing. Pour into the kadhi.","Add coriander. Sweet and tangy, serve with khichdi or rice. Skip ginger for a Jain kadhi."],"kala_chana":["Kala Chana Curry","Soak the kala chana overnight.","Pressure cook it with salt and water for 6 to 7 whistles till soft.","Heat oil, add cumin and fry onion till brown. Add ginger, garlic, green chilli, tomato and all powder spices. Cook till the oil separates.","Add the chana with its water and simmer for 10 minutes. Add amchur and coriander. Serve with rice, roti or puri."],"tomato_pappu":["Tomato Pappu","Pressure cook the toor dal with chopped tomatoes, onion, green chillies, turmeric and water for 3 to 4 whistles.","Mash everything well with a ladle. Add salt, red chilli and tamarind water, and boil for 3 minutes.","Heat oil, add mustard seeds, cumin, crushed garlic, dry red chillies, curry leaves and hing. Pour over the dal.","Add coriander and serve with hot rice and ghee, Andhra style."],"dalma":["Dalma","Dry roast the cumin and dry red chillies, cool and grind to a powder.","Pressure cook the toor dal with chopped pumpkin, brinjal, potato, tomato, turmeric, salt, ginger and water for 2 to 3 whistles. Keep the vegetables in big pieces.","Heat ghee, add panch phoron and fry till it crackles. Pour it into the dal.","Add the roasted cumin-chilli powder and grated coconut. Boil for 2 minutes. Serve with rice, the Odia way."],"kerala_kadala":["Kadala Curry","Soak the kala chana overnight, then pressure cook it with salt and water for 6 to 7 whistles.","Roast the grated coconut in a dry pan till brown and fragrant. Add the powder spices, roast 1 minute, cool and grind to a paste with water.","Heat coconut oil. Add mustard seeds, curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste and the chana with its water. Simmer for 10 minutes. Serve with puttu or appam, or rice."],"ghugni":["Ghugni","Soak the dried peas overnight.","Pressure cook them with salt and turmeric for 3 to 4 whistles, till soft but whole.","Heat mustard oil. Add cumin and bay leaf, then onion, ginger and garlic. Fry till golden. Add small potato cubes and tomato, red chilli and salt; cook till soft.","Add the peas with their water and simmer for 10 minutes. Add garam masala.","Serve hot topped with chopped onion, coriander and lemon. A favourite evening snack in Bengal and Odisha."],"aloo_tamatar":["Aloo Tamatar Sabzi","Peel the potatoes and cut them into small cubes. Chop the onion and tomatoes.","Heat oil in a kadhai or cooker. Add cumin, then the onion, and fry till light golden.","Add the tomatoes, turmeric, red chilli, coriander powder and salt. Cook till the tomatoes turn soft.","Add the potatoes and water. Cover and cook for 12 to 15 minutes (or 2 whistles in a cooker) till the potatoes are soft.","Add garam masala and coriander. Serve with puri, roti or paratha."],"aloo_gobi":["Aloo Gobi","Cut the cauliflower into florets and soak them in warm salted water for 10 minutes. Cut the potatoes into cubes.","Heat oil. Add cumin, then onion, ginger and green chilli. Fry for 2 minutes.","Add tomato and the powder spices with salt. Cook for 2 minutes.","Add the potatoes and cauliflower, mix well, cover and cook on low heat, stirring now and then, till soft. Do not add water.","Sprinkle garam masala, amchur and coriander. Serve with roti."],"bhindi_masala":["Bhindi Masala","Wash the bhindi and dry it fully with a cloth. Cut off the ends and slice it into pieces.","Heat oil. Add cumin, then the bhindi. Cook on medium heat without a lid, stirring gently, till it is no longer sticky.","Add sliced onion and cook till soft. Add tomato if you like.","Add turmeric, red chilli, coriander powder and salt. Cook for 3 minutes. Add amchur and serve with roti."],"baingan_bharta":["Baingan Bharta","Rub a little oil on the big brinjal and roast it directly on a gas flame, turning often, till the skin is black and the inside is soft.","Cool it, peel off the burnt skin and mash the inside well.","Heat oil. Add cumin, then chopped onion, garlic, ginger and green chilli. Fry till golden.","Add tomatoes, turmeric, red chilli and salt. Cook till soft.","Add the mashed brinjal and cook for 5 minutes. Add coriander and serve with roti."],"palak_paneer":["Palak Paneer","Wash the spinach and put it in boiling water for 2 minutes. Put it into cold water at once, then grind it with green chillies into a smooth puree.","Heat oil and butter. Add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add chopped tomato, red chilli and salt. Cook till soft.","Add the spinach puree and a little water. Cook for 4 to 5 minutes.","Add paneer cubes and garam masala, cook for 2 minutes and stir in cream. Serve with roti or rice."],"matar_paneer":["Matar Paneer","Grind the onion, ginger, garlic and green chilli to a paste. Puree the tomatoes separately.","Heat oil, add cumin and the onion paste. Fry till it turns light brown.","Add tomato puree and all the powder spices except garam masala. Cook till the oil separates.","Add peas, salt and water. Cover and cook till the peas are soft.","Add paneer cubes and garam masala. Simmer 3 minutes, add coriander and serve."],"paneer_bhurji":["Paneer Bhurji","Heat butter, add cumin, then chopped onion, green chilli and capsicum. Fry for 2 to 3 minutes.","Add chopped tomato, turmeric, red chilli and salt. Cook till soft.","Crumble the paneer into the pan, mix and cook for 2 minutes only, so it stays soft.","Add garam masala and coriander. Great with roti, in a sandwich or a roll."],"mix_veg":["Mixed Vegetable Sabzi","Cut all the vegetables into small, equal pieces so they cook together.","Heat oil, add cumin, then chopped onion, ginger and garlic. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add the vegetables and water. Cover and cook till they are soft but not mushy.","Add garam masala. Serve with roti or rice."],"jeera_aloo":["Jeera Aloo","Boil the potatoes till just soft, cool, peel and cut them into cubes. (Leftover boiled potatoes work well.)","Heat oil. Add plenty of cumin and let it sizzle, then add green chilli.","Add the potatoes and all the spices with salt. Toss and cook on medium heat for 5 minutes till the edges turn crisp.","Add lots of coriander. Good in tiffin with puri or roti. No onion or garlic needed."],"lauki_sabzi":["Lauki Sabzi","Peel the lauki, taste a small piece (throw it away if it is bitter) and cut into small cubes.","Heat oil. Add cumin, hing and green chilli.","Add chopped tomato and the spices with salt. Cook for 2 minutes.","Add the lauki, cover and cook on low heat for 12 to 15 minutes. It cooks in its own water. Add coriander and serve. A light Jain-friendly sabzi."],"cabbage_poriyal":["Cabbage Poriyal","Chop the cabbage very fine.","Heat oil. Add mustard seeds, urad dal, dry red chilli, green chilli, curry leaves and hing. Fry till the dal turns golden.","Add the cabbage, turmeric and salt. Sprinkle a little water, cover and cook for 6 to 8 minutes. It should stay a little crunchy.","Add grated coconut, mix and serve with rice and sambar."],"beans_poriyal":["Beans Poriyal","Wash the beans and chop them into small pieces.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the beans and salt, sprinkle some water, cover and cook on low heat till soft.","Add grated coconut, mix well and serve."],"avial":["Avial","Cut all the vegetables into finger-long sticks.","Cook them with turmeric, salt and a little water till just soft.","Grind the coconut, green chillies and cumin coarsely without much water.","Add the coconut paste to the vegetables and cook for 3 to 4 minutes. Turn off the heat and mix in whisked curd.","Pour raw coconut oil on top and add curry leaves. Cover for a few minutes and serve. Part of the Onam sadya."],"aloo_posto":["Aloo Posto","Soak the poppy seeds in a little warm water for 20 minutes, then grind them with 2 green chillies to a fine paste.","Heat mustard oil. Add kalonji and a slit green chilli, then potato cubes. Fry for 5 minutes.","Add turmeric, salt and a little water. Cover and cook till the potatoes are soft.","Add the poppy paste and mix well. Cook for 2 to 3 minutes. Drizzle a little raw mustard oil and serve with rice."],"begun_bhaja":["Begun Bhaja","Cut the round brinjal into thick round slices. Rub them with turmeric, red chilli, salt and sugar. Leave for 5 minutes.","Heat mustard oil in a flat pan and fry the slices on medium heat, 3 to 4 minutes on each side, till soft inside and brown outside.","Serve hot with dal and rice."],"dum_aloo":["Kashmiri Dum Aloo","Boil small baby potatoes till just done, peel them and prick them all over with a fork.","Fry the potatoes in mustard oil till golden. Take them out.","In the same oil, add cumin, cloves, cardamom, cinnamon and hing. Turn off the heat and add red chilli mixed in 2 tablespoons water.","Whisk the curd with fennel powder and sonth. Add it to the pan slowly while stirring, then add water and salt.","Add the potatoes, cover and cook on low heat for 15 minutes till the gravy is thick. No onion, garlic or tomato."],"karela_fry":["Karela Onion Fry","Scrape the karela lightly, slice it thin and remove big seeds. Rub with salt and keep for 20 minutes, then squeeze out the bitter juice.","Heat oil and fry the karela on medium heat till it turns brown and crisp.","Add sliced onions and cook till soft and brown.","Add all the spices, sugar and a little salt. Cook for 2 minutes and serve with dal-rice."],"khatta_meetha_kaddu":["Khatta Meetha Kaddu","Peel the pumpkin and cut it into cubes.","Heat oil. Add methi seeds, fennel and hing.","Add the pumpkin, turmeric, red chilli, coriander powder and salt. Cover and cook on low heat till soft, stirring once or twice.","Mash it lightly, add jaggery and amchur, and cook for 2 to 3 minutes. Sweet and sour, it goes well with puri."],"methi_aloo":["Aloo Methi","Pick the methi leaves, wash them well and chop. Cut the potatoes into small cubes.","Heat oil. Add cumin, crushed garlic and green chilli.","Add potatoes, turmeric, red chilli and salt. Cover and cook till nearly soft.","Add methi leaves and cook without a lid for 5 minutes till they wilt. Serve with roti."],"besan_shimla_mirch":["Besan Shimla Mirch","Dry roast the besan in a pan on low heat till it smells nutty. Keep aside.","Heat oil. Add mustard seeds, cumin and hing.","Add chopped capsicum, turmeric and salt. Cook for 5 to 6 minutes till soft.","Add red chilli, coriander powder, sugar and the roasted besan. Mix and cook for 2 to 3 minutes. Jain-friendly."],"kadai_paneer":["Kadai Paneer","Cut paneer, capsicum and 1 onion into cubes. Crush the dry red chillies coarsely.","Heat 1 tablespoon oil and toss the capsicum and onion cubes on high heat for 2 to 3 minutes. Take them out.","Add the rest of the oil. Fry the other chopped onion, ginger and garlic, then tomato puree, crushed chillies and spices. Cook till the oil separates.","Add paneer, capsicum and onion with a little water. Cook for 2 to 3 minutes. Add crushed kasuri methi and coriander."],"mushroom_matar":["Mushroom Matar","Wash the mushrooms quickly, wipe them dry and slice them.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the powder spices; cook till soft.","Add peas and mushrooms with salt. Cook on high heat for 5 to 6 minutes; the mushrooms will give out water.","Add a little water if needed and garam masala. Cook 2 to 3 minutes more and serve with roti."],"beetroot_poriyal":["Beetroot Poriyal","Peel and grate or finely chop the beetroot.","Heat oil. Add mustard seeds, urad dal, green chilli and curry leaves.","Add beetroot and salt, sprinkle water, cover and cook for 8 to 10 minutes till soft.","Add coconut and mix. Bright and healthy, kids like its colour."],"gajar_matar":["Gajar Matar","Peel and cut the carrots into small cubes.","Heat oil. Add cumin, hing and grated ginger.","Add carrots, peas, the spices and salt. Sprinkle a little water, cover and cook till soft.","A simple winter sabzi, good with roti. No onion or garlic."],"paneer_butter_masala":["Paneer Butter Masala","Cook the chopped tomatoes, onion, cashews, ginger and garlic with 1/2 cup water till soft. Cool and grind to a very smooth paste.","Heat butter, add red chilli and then the paste. Cook on low heat, stirring, till it thickens and leaves butter at the sides.","Add water, salt, sugar and garam masala. Bring to a boil.","Add paneer cubes, crushed kasuri methi and cream. Simmer for 2 to 3 minutes. Serve with naan, roti or jeera rice."],"aloo_matar":["Aloo Matar","Heat oil, add cumin, then chopped onion, ginger and green chilli. Fry till golden.","Add tomatoes and the powder spices with salt. Cook till the oil separates.","Add potato cubes, peas and water. Pressure cook for 2 whistles, or cover and cook till soft.","Add garam masala and coriander. Serve with roti, puri or rice."],"soya_curry":["Soya Chunks Curry","Boil the soya chunks in salted water for 5 minutes. Drain, rinse in cold water and squeeze out all the water.","Heat oil, add cumin, then onion, ginger and garlic. Fry till golden. Add tomato and the spices; cook till the oil separates.","Add the soya chunks and water. Cover and simmer for 10 minutes.","Add garam masala and coriander. Rich in protein, a good veg option."],"sarson_saag":["Sarson ka Saag","Wash the mustard greens and spinach in plenty of water and chop them, stems and all.","Pressure cook the greens with ginger, garlic, green chillies, salt and a little water for 3 to 4 whistles.","Mash or blend them coarsely. Stir in the maize flour and cook on low heat for 10 minutes, stirring.","Heat ghee, fry chopped onion and a little garlic till golden and pour over the saag.","Serve with makki ki roti, a dollop of white butter and jaggery. A winter and Lohri favourite in Punjab."],"egg_curry":["Egg Curry","Boil the eggs for 10 minutes, cool them in water, peel and make 2 small cuts on each.","Heat oil, add a pinch of turmeric and red chilli, and fry the eggs lightly. Take them out.","In the same oil, fry chopped onion till brown. Add ginger, garlic, green chilli, tomatoes and the spices with salt. Cook till the oil separates.","Add water, bring to a boil, add the eggs and simmer for 5 to 8 minutes. Add garam masala and coriander. Serve with rice or roti."],"chicken_curry":["Chicken Curry","Wash the chicken and mix it with curd, turmeric, red chilli and salt. Keep it for 30 minutes (or overnight in the fridge).","Heat oil. Add the whole spices, then sliced onion. Fry till deep golden brown, stirring often.","Add ginger-garlic paste and green chilli, fry 1 minute. Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add the chicken and fry on high heat for 5 to 8 minutes.","Add water, cover and cook on low heat for 20 minutes till the chicken is soft and fully cooked. Add garam masala and coriander."],"machher_jhol":["Machher Jhol","Rub the fish pieces with turmeric and salt. Heat mustard oil till it smokes, fry the fish lightly on both sides and take it out.","In the same oil, add kalonji and slit green chillies, then potato sticks. Fry for 3 to 4 minutes.","Add ginger paste, chopped tomato, turmeric, red chilli, cumin powder and salt. Cook for 2 to 3 minutes.","Add water. When it boils, add the fish. Cook on low heat for 8 to 10 minutes, till the potatoes are soft. Add coriander. A light Bengali fish curry for rice."],"fish_curry_coconut":["Coconut Fish Curry","Rub the fish with turmeric and salt. Soak tamarind in warm water and squeeze out the juice.","Grind the coconut with red chilli, coriander powder, turmeric and a little water into a smooth paste.","Heat coconut oil, add curry leaves, then sliced onion, ginger and garlic. Fry till soft.","Add the coconut paste, tamarind water, salt and water. Bring to a gentle boil.","Slide in the fish pieces and simmer on low heat for 8 to 10 minutes. Do not stir hard. Serve with rice, as in Goa, Mangalore and Kerala."],"mutton_curry":["Mutton Curry","Mix the mutton with curd, ginger-garlic paste, turmeric, red chilli and salt. Keep for 1 hour or more.","Heat oil, add the whole spices and sliced onion. Fry till deep brown.","Add the mutton and fry on high heat, stirring, for 10 minutes till it changes colour.","Add chopped tomatoes and coriander powder. Cook till the oil separates.","Add hot water and pressure cook for 6 to 8 whistles (about 30 minutes) till the meat is soft. Add garam masala and serve with rice or roti."],"prawn_masala":["Prawn Masala","Clean the prawns, remove the black vein and mix with turmeric, salt and lemon juice. Keep for 10 minutes.","Heat oil, fry chopped onion till golden, then add ginger-garlic paste and tomato. Cook till soft.","Add red chilli and coriander powder with a splash of water and cook for 1 to 2 minutes.","Add the prawns and kokum. Cook for 5 to 6 minutes only, till the prawns turn pink and curl. Do not overcook. Add coriander."],"kerala_egg_roast":["Kerala Egg Roast","Hard boil the eggs, peel them and make a few cuts on each.","Heat coconut oil, add curry leaves and thinly sliced onions with salt. Cook slowly till soft and golden brown.","Add ginger, garlic and green chillies, then all the powder spices. Fry for 1 minute, then add tomato and cook till mushy.","Add the eggs and a splash of water. Coat them well in the thick masala and cook for 5 minutes. Serve with appam, parotta or rice."],"kerala_stew":["Kerala Vegetable Stew","Grate the coconut and grind it with warm water. Squeeze through a cloth to get thick milk. Grind again with more water to get a thin milk.","Heat coconut oil. Add cinnamon, cloves, cardamom, then sliced onion, ginger, green chillies and curry leaves. Fry without browning.","Add cubed vegetables, salt, pepper and the thin coconut milk. Cover and cook till the vegetables are soft.","Lower the heat, add the thick coconut milk and heat gently for 2 minutes. Do not boil. Serve with appam or idiyappam."],"plain_rice":["Steamed Rice","Wash the rice 2 or 3 times till the water runs clear. Soak it for 20 minutes if you have time.","Put the rice and water (2 cups water for 1 cup rice) in a cooker with salt and ghee.","Cook for 2 whistles on medium heat, then turn off the heat.","Wait till the pressure drops by itself, then fluff the rice gently with a fork."],"jeera_rice":["Jeera Rice","Wash basmati rice and soak it for 20 minutes. Drain.","Heat ghee in a pot. Add cumin and the whole spices and let them sizzle.","Add the rice and fry gently for 1 to 2 minutes.","Add water and salt. Boil, then cover and cook on very low heat for 12 minutes till the water is absorbed.","Rest it covered for 5 minutes, fluff with a fork and add coriander. Great with dal makhani or rajma."],"veg_pulao":["Vegetable Pulao","Wash and soak the rice for 20 minutes. Cut the vegetables into small pieces.","Heat ghee in a cooker. Add cumin, bay leaf and whole spices, then sliced onion, ginger, garlic and green chilli. Fry till light golden.","Add the vegetables and fry for 2 minutes. Add the drained rice and mix gently.","Add water and salt. Close and cook for 1 to 2 whistles. Let the pressure drop by itself.","Fluff gently and serve with raita."],"lemon_rice":["Lemon Rice","Use cooked rice that has cooled down, so the grains stay separate.","Heat oil. Fry peanuts till crisp. Add mustard seeds, urad dal, chana dal, chillies, curry leaves and hing.","Turn the heat low, add turmeric and salt.","Add the rice and mix gently. Turn off the heat, squeeze in the lemon juice and mix. A perfect tiffin and travel food."],"curd_rice":["Curd Rice","Mash soft cooked rice lightly while it is still a little warm. Let it cool.","Mix in curd, salt and milk (milk stops it from turning too sour in a tiffin box).","Heat oil. Add mustard seeds, urad dal, chopped green chilli, ginger, curry leaves and hing. Pour over the rice.","Add grated cucumber and coriander. Serve cool with pickle. Very soothing in summer."],"tomato_rice":["Tomato Rice","Heat oil, add mustard seeds and curry leaves, then sliced onion, ginger, garlic and green chilli. Fry till soft.","Add chopped tomatoes, turmeric, red chilli, garam masala and salt. Cook till the tomatoes turn mushy.","Add washed rice and water. Cook for 2 whistles in a cooker.","Fluff, add coriander and pack it in a tiffin with raita or chips."],"moong_khichdi":["Moong Dal Khichdi","Wash the rice and moong dal together and soak for 10 minutes.","Heat 1 tablespoon ghee in a cooker. Add cumin, hing and grated ginger.","Add rice, dal, turmeric, salt and water. Cook for 4 to 5 whistles till soft and mushy.","Add the rest of the ghee on top. Serve with curd, papad and pickle. Comfort food for all ages."],"veg_biryani":["Vegetable Biryani","Soak basmati rice for 20 minutes. Boil it in lots of salted water with bay leaf and whole spices till 70% cooked. Drain.","Fry thinly sliced onions in ghee and oil till deep brown. Keep half aside for the top.","To the rest of the onions, add ginger-garlic, green chilli, the vegetables, curd, red chilli, turmeric, garam masala and salt. Cook till the vegetables are nearly soft.","Spread the rice over the vegetables. Top with fried onions, mint, coriander, saffron soaked in milk and a spoon of ghee.","Cover tightly and cook on very low heat (dum) for 20 minutes. Mix gently from the side and serve with raita."],"chicken_biryani":["Chicken Biryani","Mix the chicken with curd, ginger-garlic paste, red chilli, turmeric, garam masala, lemon juice, mint, coriander and salt. Keep for 1 hour.","Fry sliced onions in ghee and oil till deep brown and crisp. Mix half into the chicken.","Soak the rice for 20 minutes, then boil it in plenty of salted water with whole spices till 70% done. Drain.","Cook the chicken in a heavy pot for 15 minutes on medium heat till it is nearly done and the masala is thick.","Spread the rice on top, add fried onions, mint, saffron milk and ghee. Seal with a lid and cook on very low heat for 20 to 25 minutes. Serve with raita."],"egg_fried_rice":["Egg Fried Rice","Use cold cooked rice (leftover rice is best). Chop the vegetables and garlic very fine.","Heat 1 tablespoon oil, scramble the eggs with a pinch of salt and take them out.","Heat the rest of the oil on high heat. Fry garlic and green chilli, then the vegetables for 2 to 3 minutes. They should stay crunchy.","Add rice, eggs, salt and pepper. Toss on high heat for 2 to 3 minutes and serve hot."],"puliyogare":["Puliyogare (Tamarind Rice)","Soak the tamarind in 1 cup warm water and squeeze out thick juice. Spread cooked rice on a plate to cool.","Heat oil. Fry peanuts, then add mustard seeds, chana dal, urad dal, dry red chillies, curry leaves and hing.","Add tamarind juice, turmeric, jaggery and salt. Boil till it turns thick like a paste and oil floats on top.","Dry roast and powder the sesame and methi seeds. Mix the tamarind paste and powder into the rice. Tastes even better after an hour; great for travel. Jain-friendly."],"coconut_rice":["Coconut Rice","Spread cooked rice to cool so the grains stay separate.","Heat coconut oil. Add mustard seeds, urad dal, chana dal and cashews; fry till golden. Add chillies, curry leaves and hing.","Add fresh grated coconut and salt. Stir for 1 to 2 minutes, just till it smells nice.","Mix in the rice gently. Mild and tasty, good in a tiffin box."],"bhuna_khichuri":["Bhoger Khichuri","Dry roast the moong dal till golden and fragrant. Wash it with the rice.","Heat ghee. Fry the cauliflower and potato pieces lightly and take them out.","In the same ghee, add cumin, bay leaves, dry red chillies and ginger paste. Add turmeric and red chilli.","Add rice, dal, tomato and hot water. Cook on medium heat for 15 minutes, add the fried vegetables, peas, salt and sugar, and cook till everything is soft.","Add a spoon of ghee and garam masala. The Durga Puja bhog khichuri, made with no onion or garlic."],"pakhala":["Pakhala Bhata","Put cooked rice (leftover rice is perfect) in a bowl and pour cold water over it.","Mix in curd and salt. You can leave it for a few hours to turn a little sour.","For tadka, heat a little oil, add mustard seeds, curry leaves and green chilli, and pour it over.","Serve with raw onion, lemon and fried or roasted vegetables. Odisha's cooling summer meal."],"roti":["Roti (Phulka)","Knead the atta with a pinch of salt and water, little by little, into a soft dough. Cover and rest for 15 minutes.","Make lemon-sized balls. Dip in dry flour and roll into thin, even circles.","Put on a hot tawa. When small bubbles appear, flip it. Cook the other side for a few seconds.","Hold it with tongs over an open flame for a few seconds so it puffs up. Apply ghee and keep in a covered box."],"plain_paratha":["Plain Paratha","Knead a soft dough with atta, salt, ajwain and water. Rest it for 10 minutes.","Roll a ball into a circle, spread ghee, sprinkle a little flour and fold it into a triangle (or roll it up and coil it).","Roll it out again gently into a thick triangle or round.","Cook on a hot tawa, flipping and applying ghee on both sides, till you see golden layers. Serve with any sabzi or curd."],"gobi_paratha":["Gobi Paratha","Knead a soft dough with atta and water and rest it for 15 minutes.","Grate the cauliflower finely. Mix with chilli, ginger, coriander and spices. Add salt only just before filling, and squeeze out any water.","Fill a ball of dough with the gobi mix, seal it and roll gently with dry flour.","Cook on a hot tawa with ghee on both sides till crisp and golden. Serve with curd and butter."],"paneer_paratha":["Paneer Paratha","Knead a soft dough with atta and water and rest for 15 minutes.","Grate the paneer and mix it with very finely chopped onion, chilli, coriander, spices and salt.","Stuff a ball of dough with the paneer filling, seal and roll gently.","Cook on a hot tawa with ghee till both sides are golden. Soft and filling, kids love it in tiffin."],"missi_roti":["Missi Roti","Mix besan, atta, chopped onion, chilli, coriander, all spices and salt. Knead a firm dough with water and rest for 10 minutes.","Roll the balls into thick rotis, using dry flour.","Cook on a hot tawa on both sides, then roast over the flame or press on the tawa till spotted. Apply ghee. Serve with dal or curd."],"jowar_bhakri":["Jowar Bhakri","Add salt to the jowar flour. Pour hot water little by little and knead well with your palm for a few minutes till smooth.","Take a ball of dough and pat it flat with your palm on a floured board, turning it as you go. Or press it between two sheets.","Put it on a hot tawa, wipe the top with a little water and flip when the water dries.","Cook till spotted on both sides, then puff it on the flame. Serve with pithla, thecha or any sabzi."],"makki_roti":["Makki ki Roti","Mix maize flour with salt and ajwain. Add warm water a little at a time and knead with your palm for 5 minutes till smooth.","Take a ball and pat it into a thick roti between your palms, or press it on a plastic sheet with wet hands.","Cook on a medium-hot tawa on both sides till spotted, then add ghee.","Serve hot with sarson ka saag, white butter and jaggery."],"pithla":["Pithla","Whisk the besan with water and salt into a smooth, lump-free batter.","Heat oil. Add mustard seeds, cumin, hing, curry leaves, crushed garlic and green chilli, then chopped onion. Fry till soft.","Add turmeric, then pour in the besan batter, stirring all the time. Cover and cook on low heat for 5 to 6 minutes till thick.","Add coriander. Serve with bhakri or rice: a quick Maharashtrian village meal."],"onion_pakora":["Onion Pakora","Slice the onions thin, add salt and leave for 10 minutes so they give out water.","Add besan, chopped chilli, ajwain, spices and coriander. Mix, adding just a little water, so the batter coats the onions.","Heat oil. Drop small, loose bunches into the oil and fry on medium heat till crisp and golden.","Drain on paper and serve hot with chutney and chai. Perfect on a rainy day."],"aloo_tikki":["Aloo Tikki","Boil and peel the potatoes, cool and mash them well.","Add mashed peas, chilli, ginger, coriander, spices, salt and besan (or bread crumbs) to bind. Mix well.","Make flat round tikkis with oiled hands.","Shallow fry on a tawa on medium heat, 3 to 4 minutes on each side, till crisp and golden. Serve with chutney, curd and chaat masala."],"bhel_puri":["Bhel Puri","Chop onion, tomato, boiled potato, chilli and coriander finely.","For quick sweet chutney, mix tamarind pulp with jaggery and a pinch of salt.","Just before eating, mix puffed rice with the vegetables, peanuts, chutney, lemon juice, chaat masala and salt.","Top with sev and eat at once, before it turns soggy. Mumbai beach style."],"vada_pav":["Vada Pav","Boil, peel and mash the potatoes. Crush garlic, ginger and green chillies together.","Heat 1 tablespoon oil. Add mustard seeds, hing, curry leaves, the crushed paste and turmeric, then the potatoes, salt and coriander. Mix and cool. Make round balls.","Mix besan, a pinch of turmeric, salt and water into a thick, smooth batter.","Dip each ball in the batter and deep fry in hot oil till golden.","Slit the pav, add chutney, put a hot vada inside and press. Serve with fried green chillies."],"pav_bhaji":["Pav Bhaji","Pressure cook the potatoes, cauliflower and peas till very soft. Mash them well.","Heat 2 tablespoons butter. Fry 1 chopped onion and garlic, then chopped capsicum and tomatoes till mushy.","Add the masala, red chilli, turmeric, salt and the mashed vegetables. Mash everything together in the pan, add water and cook for 10 minutes.","Slit the pav and toast it on a tawa with butter and a pinch of pav bhaji masala.","Serve the bhaji with butter on top, chopped onion, coriander and lemon, with hot pav."],"masala_corn":["Masala Corn","Boil the corn kernels in salted water for 4 to 5 minutes (or steam them). Drain.","Toss them while hot with butter, salt, red chilli and chaat masala.","Squeeze lemon, add coriander and serve in cups. A healthy evening snack."],"medu_vada":["Medu Vada","Soak the urad dal for 4 hours. Drain well.","Grind it with very little water into a thick, fluffy batter. Beat it with your hand for 2 to 3 minutes to make it light.","Mix in chopped ginger, chilli, curry leaves, crushed pepper, onion, coconut and salt.","With wet hands, shape a ball, flatten it, make a hole in the centre and slide it into hot oil. Fry on medium heat till crisp and golden.","Serve hot with coconut chutney and sambar."],"jhal_muri":["Jhal Muri","Chop onion, cucumber, tomato, chilli and coriander finely.","Put the puffed rice in a big bowl or a steel box.","Add the vegetables, peanuts, salt, chaat masala and raw mustard oil. Close the box and shake well, or toss with a spoon.","Squeeze lemon and eat right away. Kolkata's favourite train snack."],"paneer_tikka":["Tawa Paneer Tikka","Mix thick curd with ginger-garlic paste, roasted besan, the spices, lemon juice, 1 tablespoon oil and salt.","Add cubes of paneer, capsicum and onion. Coat well and keep for 30 minutes.","Put them on skewers or toothpicks, or cook them loose.","Cook on a hot greased tawa or grill pan, turning, till charred at the edges. Sprinkle chaat masala and serve with green chutney."],"roasted_makhana":["Roasted Makhana","Heat ghee in a pan on low heat. Add the makhana and roast, stirring often, for 5 to 6 minutes till crunchy. Press one: it should break with a crunch.","Turn off the heat, sprinkle salt, pepper, turmeric and chaat masala, and toss well.","Cool and store in an airtight jar. A light, healthy snack, also eaten on fasts."],"sundal":["Chana Sundal","Use chickpeas that are soaked overnight and pressure cooked till soft. Drain.","Heat oil. Add mustard seeds, urad dal, dry red chilli, curry leaves and hing.","Add the chickpeas and salt, toss for 2 to 3 minutes.","Turn off the heat and mix in grated coconut. Made as prasad during Navratri and Ganesh Chaturthi."],"sprouts_chaat":["Sprouts Chaat","Steam or boil the sprouts for 2 to 3 minutes so they are tender but still crunchy. Cool.","Chop onion, tomato, cucumber, chilli and coriander.","Mix everything with lemon juice, chaat masala and salt. Eat fresh. Full of protein."],"paneer_roll":["Paneer Kathi Roll","Heat butter. Toss sliced onion and capsicum on high heat for 2 minutes.","Add paneer strips, the spices and salt. Toss gently for 2 to 3 minutes.","Make 4 thin rotis, or warm leftover rotis on a tawa.","Put the filling on a roti, add sliced onion, lemon and chaat masala, and roll it up tightly. Wrap in foil or paper for the tiffin box."],"cheese_corn_sandwich":["Cheese Corn Sandwich","Boil the corn for 3 minutes and drain. Mix with grated cheese, chopped capsicum, pepper and a pinch of salt.","Butter the bread slices and spread the filling on two of them. Cover with the other slices.","Toast on a tawa or in a sandwich maker till golden and the cheese melts. Cut and pack."],"semiya_upma":["Semiya Upma","Dry roast the vermicelli till light brown (skip if it is already roasted).","Heat oil. Add mustard seeds, urad dal, curry leaves, chilli and ginger, then onion, carrot and peas. Fry till soft.","Add water and salt and bring to a boil.","Add the vermicelli, stir, cover and cook on low heat till the water is absorbed. Fluff, add lemon juice. A quick tiffin."],"masala_pasta":["Desi Masala Pasta","Boil the pasta in plenty of salted water till soft. Drain and keep a little of the water.","Heat oil. Fry garlic and onion, then capsicum and carrot for 2 minutes.","Add chopped tomatoes, red chilli, garam masala and salt. Cook till it turns into a thick sauce.","Add the pasta and a splash of the pasta water. Toss well, top with grated cheese. Kids love it in tiffin."],"suji_halwa":["Suji Halwa (Sheera)","Boil the water with sugar in a pan till the sugar melts. Keep it hot.","In another pan, heat ghee and roast the suji on low heat, stirring all the time, till golden and nutty. Add cashews and raisins.","Carefully pour in the hot sugar water (it will splutter) and stir fast so no lumps form.","Cook till it leaves the sides of the pan. Add cardamom powder. Offer as prasad or enjoy warm."],"rice_kheer":["Rice Kheer","Wash and soak the rice for 15 minutes. Drain.","Boil the milk in a heavy pan.","Add the rice and cook on low heat, stirring often and scraping the bottom, till the rice is very soft and the milk is thick and creamy.","Add sugar, cardamom powder, saffron and chopped nuts. Cook for 2 to 3 minutes. Serve warm or chilled."],"gajar_halwa":["Gajar ka Halwa","Wash, peel and grate the red winter carrots.","Cook the grated carrots with milk in a heavy kadhai on medium heat, stirring often, till all the milk dries up.","Add ghee and sugar. Keep cooking and stirring till the halwa leaves the sides and looks glossy.","Add cardamom powder and fried nuts and raisins. A winter and Diwali favourite."],"seviyan_kheer":["Seviyan Kheer","Heat ghee and roast the vermicelli and nuts till golden.","Add milk and bring it to a boil, stirring.","Cook on low heat for 8 to 10 minutes till the vermicelli is soft and the milk thickens a little.","Add sugar, cardamom and raisins. Serve warm or cold. Made on Eid and many happy days."],"besan_ladoo":["Besan Ladoo","Heat ghee in a heavy kadhai. Add besan and roast on low heat, stirring all the time, for 15 to 20 minutes till it turns golden and smells nutty.","Turn off the heat and let it cool till just warm.","Grind the sugar to a fine powder. Mix it into the besan with cardamom powder and chopped nuts.","Press handfuls into round ladoos. Store in an airtight box for up to 2 weeks."],"coconut_ladoo":["Coconut Ladoo (Nariyal Ladoo)","Melt the jaggery with 2 tablespoons water on low heat. Strain it if there is any dirt.","Add the grated coconut and ghee. Cook, stirring, till the mix comes together and leaves the sides.","Add cardamom powder and broken cashews. Cool till you can touch it.","Grease your palms and roll into small ladoos."],"shrikhand":["Shrikhand","Tie the curd in a thin cotton cloth and hang it in the fridge for 5 to 6 hours till all the water drips out.","Soak saffron in a spoon of warm milk.","Whisk the thick hung curd with powdered sugar till smooth and creamy. Add cardamom and saffron milk.","Chill and serve topped with nuts. Lovely with puri on Gudi Padwa."],"sandesh":["Sandesh","Boil the milk. Turn off the heat, wait 1 minute, then add lemon juice mixed with water little by little till the milk splits.","Strain through a cotton cloth, rinse with cold water to remove the lemon taste, and hang for 20 minutes. This soft white chhena is homemade paneer.","Knead the chhena with your palm for 5 minutes till smooth. Mix in powdered sugar.","Cook it in a pan on very low heat for 4 to 5 minutes, stirring, till it just comes together. Do not overcook.","Add cardamom, cool slightly and shape into small rounds. Press a strand of saffron on each."],"kada_prasad":["Atta Halwa (Kada Prasad)","Boil the water and sugar together till the sugar melts. Keep hot.","Heat ghee in a heavy kadhai. Add the atta and roast on low to medium heat, stirring all the time, till it turns deep golden and smells wonderful.","Pour in the hot sugar water carefully and stir hard. Keep stirring till the halwa leaves the sides and the ghee shines.","Served as prasad at gurdwaras. Simple, with just 4 ingredients."],"modak":["Ukadiche Modak","For the filling, cook grated coconut and jaggery together till the jaggery melts and the mix thickens. Add cardamom. Cool.","Boil the water with salt and a spoon of ghee. Add the rice flour, stir, cover and leave for 5 minutes.","Knead the warm dough with wet hands till very smooth.","Flatten a ball into a small cup, put filling inside, pinch the edges into pleats and close them at the top.","Steam on a greased plate for 10 to 12 minutes. Serve with a little ghee. Ganpati Bappa's favourite."],"puran_poli":["Puran Poli","Pressure cook the chana dal with water for 4 to 5 whistles till soft. Drain well.","Knead a very soft dough with atta, maida, turmeric, salt, oil and water. Rest it for 1 hour.","Cook the dal with jaggery in a pan, stirring, till it is thick and dry. Add cardamom and mash it to a smooth puran (filling). Cool.","Stuff a ball of dough with a bigger ball of puran, seal and roll gently into a thin round with rice flour.","Cook on a tawa on both sides till golden spots appear. Serve with lots of ghee. Made on Holi and Gudi Padwa."],"sakkarai_pongal":["Sakkarai Pongal","Dry roast the moong dal till fragrant. Wash it with the rice.","Pressure cook the rice and dal with water (and milk) for 4 whistles till very soft. Mash well.","Melt the jaggery in 1/4 cup water and strain it. Add it to the rice and cook, stirring, till it blends in.","Fry cashews and raisins in ghee and add them with the ghee and cardamom powder. Cooked on the Pongal festival."],"til_ladoo":["Til Gud Ladoo","Dry roast the sesame on low heat till it crackles and smells nutty. Roast and crush the peanuts too.","Melt jaggery with ghee and 1 tablespoon water. Cook till it thickens; a drop in water should form a soft ball.","Turn off the heat, add sesame, peanuts and cardamom and mix fast.","Grease your palms and shape small ladoos while it is still warm. Made on Makar Sankranti: \"til gul ghya, god god bola\"."],"gulab_jamun":["Gulab Jamun","Boil sugar and water for 5 minutes to make a light syrup. Add crushed cardamom and keep it warm.","Mix milk powder, maida, soda and ghee. Add milk little by little and make a soft, sticky dough. Do not knead hard.","Make small, smooth balls with no cracks; they will double in size.","Fry them in oil on low heat, moving them gently, till deep brown all over. Low heat is the secret.","Put the hot jamuns into the warm syrup and soak for at least 30 minutes. A Diwali and wedding favourite."],"masala_chai":["Masala Chai","Boil the water with crushed ginger, cardamom and clove.","Add tea leaves and boil for 1 to 2 minutes.","Add milk and sugar. Let it boil up 2 or 3 times on medium heat, till it turns a rich brown.","Strain into cups and serve hot, with biscuits or pakoras."],"filter_coffee":["Filter Coffee","Put coffee powder in the top part of a coffee filter, press lightly, pour boiling water over it and close. Leave for 10 to 15 minutes to collect a thick decoction.","No filter? Boil the coffee in the water for 1 minute, cover for 5 minutes and strain through a fine cloth.","Heat the milk till it boils. Add 3 to 4 tablespoons of decoction and sugar to each cup.","Pour from one tumbler to another, high up, to make it frothy. Serve in a davara-tumbler."],"sweet_lassi":["Sweet Lassi","Put chilled curd, sugar, cardamom powder and cold water (or ice) in a jug.","Whisk or blend well for 1 to 2 minutes till frothy.","Pour into tall glasses and top with a spoon of malai. Punjab's summer drink."],"chaas":["Masala Chaas","Dry roast the cumin and crush it to a powder.","Blend or whisk the curd with cold water, grated ginger, chilli, mint, coriander, salt, black salt and the roasted cumin.","Serve cold after meals. It cools the body and helps digestion in summer."],"nimbu_pani":["Nimbu Pani (Shikanji)","Mix sugar in cold water till it dissolves.","Squeeze in the lemon juice. Add salt, black salt and roasted cumin powder.","Add ice and crushed mint leaves and serve at once. Best on a hot day."],"aam_panna":["Aam Panna","Pressure cook the raw mangoes with a cup of water for 2 to 3 whistles, or boil till soft.","Cool, peel and squeeze out all the pulp.","Blend the pulp with sugar, roasted cumin, black salt, salt and mint.","Mix 3 to 4 spoons of this in a glass of chilled water. Protects from summer heat (loo)."],"haldi_doodh":["Haldi Doodh","Heat the milk with turmeric, a pinch of crushed pepper and grated ginger. Simmer for 3 to 5 minutes.","Turn off the heat and stir in jaggery or honey once it is not too hot.","Strain and drink warm at bedtime. A home remedy for cough and cold."],"banana_shake":["Banana Milkshake","Peel and slice ripe bananas.","Blend them with chilled milk, sugar and cardamom till smooth and frothy.","Pour into glasses and top with chopped almonds. Drink fresh, an energy boost after school or play."],"sattu_sharbat":["Sattu Sharbat","Mix the sattu in a little cold water to a smooth paste, then add the rest of the water.","Add lemon juice, salt, black salt and roasted cumin powder.","Add finely chopped onion, chilli and mint if you like. Bihar's cooling protein drink for summer."],"cucumber_raita":["Cucumber Raita","Dry roast the cumin and crush it.","Grate or finely chop the cucumber and squeeze out a little water.","Whisk the curd with salt, add the cucumber, roasted cumin and chopped mint or coriander. Sprinkle red chilli. Serve with pulao or paratha."],"green_chutney":["Green Chutney","Wash the coriander and mint well. You can use the soft coriander stems too.","Grind with chilli, ginger, cumin, salt, sugar, lemon juice and a little ice-cold water till smooth.","Keeps in the fridge for 3 to 4 days. Use with chaat, sandwiches, pakoras and tikkis."],"coconut_chutney":["Coconut Chutney","Grind grated coconut, roasted gram, green chillies, ginger and salt with water till smooth.","Heat oil. Add mustard seeds, urad dal, dry red chilli and curry leaves.","Pour the tadka over the chutney. Serve with idli, dosa, vada or upma."],"tomato_chutney":["Tomato Chutney","Heat 1 tablespoon oil. Fry urad dal and dry red chillies till the dal is golden.","Add onion and garlic, fry till soft, then tomatoes and tamarind with salt. Cook till mushy.","Cool and grind to a smooth chutney.","Heat the rest of the oil, add mustard seeds, curry leaves and hing, and pour over. Good with idli, dosa or rice."]}}
};
